import java.io.IOException;

/**
 * Represents a Huffman coding tree and supports serialized representation
 */
public class HuffmanTree {
    private TreeNode root;

    // entries are indexed by value and generated by queue constructor
    private String[] codes;

    /**
     * pre: queue != null, queue is nonempty, contains leaves with values
     * from 0 to IHuffConstants.PSEUDO_EOF and has positive frequencies
     * post: constructs a Huffman tree and generates its codes, queue is empty
     * @throws IllegalArgumentException if queue is null or empty
     */
    public HuffmanTree(PriorityQueue<TreeNode> queue) {
        if (queue == null || queue.isEmpty()) {
            throw new IllegalArgumentException("Queue must be nonnull and nonempty");
        }
        while (queue.size() > 1) {
            TreeNode left = queue.dequeue();
            TreeNode right = queue.dequeue();
            TreeNode parent = new TreeNode(left, 0, right);
            queue.enqueue(parent);
        }
        root = queue.dequeue();
        codes = new String[IHuffConstants.ALPH_SIZE + 1];
        generateCodes(root, "");
    }

    /**
     * pre: current != null, currentPath != null, codes is initialized
     * post: stores code for the leaves below current using currentPath
     * as the starting path
     */
    private void generateCodes(TreeNode current, String currentPath) {
        if (current.isLeaf()) {
            codes[current.getValue()] = currentPath;
        } else {
            generateCodes(current.getLeft(), currentPath + "0");
            generateCodes(current.getRight(), currentPath + "1");
        }
    }

    /**
     * pre: input is positioned at the first ree marker, after the tree-size
     * field
     * post: reconstructs the tree and leaves input right after its
     * representation, doesn't close input or generate encoding codes
     * @throws IOException if tree data ends unexpectedly or a read fails
     * @throws IllegalArgumentException if input is null
     */
    public HuffmanTree(BitInputStream input) throws IOException {
        if (input == null) {
            throw new IllegalArgumentException("Input stream cannot be null");
        }
        root = constructTree(input);
    }

    /**
     * pre: input is positioned at the next node's marker
     * post: returns the subtree represented by the next tree data and
     * advances input past that subtree without closing it
     * @throws IOException if tree data ends unexpectedly or a read fails
     */
    private TreeNode constructTree(BitInputStream input) throws IOException {
        int marker = input.readBits(1);
        if (marker == -1) {
            throw new IOException("Tree Data ended unexpectedly");
        }
        if (marker == 1) {
            int value = input.readBits(IHuffConstants.BITS_PER_WORD + 1);
            if (value == -1) {
                throw new IOException("Tree Data ended unexpectedly");
            }
            return new TreeNode(value, 0);
        } else {
            TreeNode leftChild = constructTree(input);
            TreeNode rightChild = constructTree(input);
            return new TreeNode(leftChild, 0, rightChild);
        }
    }

    /**
     * pre: none
     * post: returns a reference to the current tree's root
     */
    public TreeNode getRoot() {
        return root;
    }

    /**
     * pre: codes has been generated by the priority-queue constructor
     * and the values must be between 0 and PSEUDO_EOF
     * post: returns the code for the value or null if absent
     * @throws IllegalStateException if codes is null
     * @throws IllegalArgumentException if value is outside the allowed range
     */
    public String getCode(int value) {
        if (codes == null) {
            throw new IllegalStateException("Codes have not been generated");
        }
        if (value < 0 || value >= codes.length) {
            throw new IllegalArgumentException("Value is outside the allowed range");
        }
        return codes[value];
    }

    /**
     * pre: none
     * post: returns the number of bits needed for the tree representation,
     * excluding the tree-size field and other header fields
     */
    public int numBits() {
        return numBitsHelper(root);
    }

    /**
     * pre: node != null and is a valid Huffman subtree
     * post: returns the number of bits needed to represent node's
     * subtree, including node markers and leaf values
     */
    private int numBitsHelper(TreeNode node) {
        if (node.isLeaf()) {
            return IHuffConstants.BITS_PER_WORD + 2;
        }
        return 1 + numBitsHelper(node.getLeft()) + numBitsHelper(node.getRight());
    }

    /**
     * pre: output != null and is open
     * post: writes the tree representation to output in preorder,
     * excluding the tree-size field, leaves output open
     * @throws IllegalArgumentException if output is null
     */
    public void treeWrite(BitOutputStream output) {
        if (output == null) {
            throw new IllegalArgumentException("Output stream cannot be null");
        }
        treeWriteHelper(root, output);
    }

    /**
     * pre: node != null and is a valid Huffman subtree, output is open
     * the leaf values fit in IHuffConstants.BITS_PER_WORD + 1 bits
     * post: writes node's subtree to output in preorder, using 0 for internal
     * nodes and 1 followed by the value for the leaves, leaves output open
     */
    private void treeWriteHelper(TreeNode node, BitOutputStream output) {
        if (node.isLeaf()) {
            output.writeBits(1, 1);
            output.writeBits(IHuffConstants.BITS_PER_WORD + 1, node.getValue());
        } else {
            output.writeBits(1, 0);
            treeWriteHelper(node.getLeft(), output);
            treeWriteHelper(node.getRight(), output);
        }
    }
}